 "content": "from collections import deque


def _shape_key(cells):
    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    return frozenset((r - min_r, c - min_c) for r, c in cells)


def transform(grid):
    h, w = len(grid), len(grid[0])

    # The left diagram is separated from the colored pieces by a blank column.
    split = next((c for c in range(w) if all(grid[r][c] == 0 for r in range(h))), w)
    left = [row[:split] for row in grid]
    out = [row[:] for row in left]

    # Find each colored object on the right, retaining its shape and color.
    seen = set()
    objects = {}
    for r in range(h):
        for c in range(split + 1, w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and split < nc < w and (nr, nc) not in seen
                            and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            objects[_shape_key(cells)] = color

    # Full-width colored rows in the left diagram are the panel boundaries.
    boundaries = [r for r, row in enumerate(left)
                  if row and row[0] != 0 and all(v == row[0] for v in row)]
    for top, bottom in zip(boundaries, boundaries[1:]):
        cells = [(r, c) for r in range(top + 1, bottom)
                 for c in range(split) if left[r][c] == 0]
        if not cells:
            continue
        color = objects.get(_shape_key(cells))
        if color is not None:
            for r, c in cells:
                out[r][c] = color
    return out
